/// `mysql.TypeBit`'s eval type is `ETInt`, so a cast to BIT produces an
/// integer -- but the value's canonical carrier is the zero-padded byte
/// string Go's `chunk.AppendDatum` stores for `KindMysqlBit`. A var-length
/// BIT chunk column can only hold those bytes; keeping the integer panicked
/// `finish_append_fixed` when a UNION projected one into such a column.
#[test]
fn test_cast_signed_to_bit_returns_zero_padded_bytes() {
    let ctx = WarningCtx::default();
    let mut bit20 = FieldType::new(C::Bit);
    bit20.set_flen(20);
    let out = cast_eval(
        "cast_signed",
        const_typed(Datum::Int(15), FieldType::new(C::LongLong)),
        bit20,
        &ctx,
    )
    .unwrap();
    assert_eq!(
        out,
        Datum::Bit(tidb_datatype::BinaryLiteral::from_uint(
            15,
            Some(tidb_datatype::BinaryLiteralWidth::try_from(3u8).unwrap())
        ))
    );

    let mut bit1 = FieldType::new(C::Bit);
    bit1.set_flen(1);
    let out = cast_eval(
        "cast_signed",
        const_typed(Datum::UInt(1), FieldType::new(C::LongLong)),
        bit1,
        &ctx,
    )
    .unwrap();
    assert_eq!(
        out,
        Datum::Bit(tidb_datatype::BinaryLiteral::from_uint(
            1,
            Some(tidb_datatype::BinaryLiteralWidth::try_from(1u8).unwrap())
        ))
    );
}

#[test]
fn test_cast_func_sig_as_real() {
    let ctx = WarningCtx::default();
    let json_three = BinaryJSON::parse("3").unwrap();
    let cases: Vec<(Expression, f64)> = vec![
        (
            const_typed(Datum::new_string("1.1".to_string()), str_ft()),
            1.1,
        ),
        (
            const_typed(Datum::Decimal(Decimal::from_f64(1.1).unwrap()), dec_ft()),
            1.1,
        ),
        (const_typed(Datum::Int(1), int_ft()), 1.0),
        (
            const_typed(Datum::Time(fixed_datetime()), FieldType::new(C::Datetime)),
            20201010101010.0,
        ),
        (
            const_typed(Datum::Duration(fixed_duration()), duration_ft(0)),
            125959.0,
        ),
        (
            const_typed(Datum::Json(json_three), FieldType::new(C::Json)),
            3.0,
        ),
    ];
    for (arg, want) in cases {
        let out = cast_eval("cast_double", arg, real_ft(), &ctx).unwrap();
        match out {
            Datum::Real(value) => assert!((value - want).abs() < 1e-6, "{want}"),
            other => panic!("expected real, got {other:?}"),
        }
    }
}

/// Go's DECIMAL→REAL signature propagates the DOUBLE display metadata back
/// onto its decimal child before execution. This metadata is observable on a
/// nested arithmetic expression even though the cast value itself is already
/// covered by `test_cast_func_sig_as_real`.
#[test]
fn cast_decimal_as_real_propagates_child_metadata() {
    let mut source_type = FieldType::new(C::NewDecimal);
    source_type.set_flen(5);
    source_type.set_decimal(2);
    let source = const_typed(Datum::Decimal(Decimal::from_literal("0.99")), source_type);
    let wrapped = crate::aggregation::wrap_cast::wrap_with_cast_as_real(source).unwrap();
    let Expression::ScalarFunction(function) = wrapped else {
        panic!("expected a cast scalar function")
    };
    let child = function.args.first().expect("cast argument");
    let child_type = child.static_type().expect("decimal child type");
    assert_eq!(child_type.code(), C::NewDecimal);
    assert_eq!(child_type.flen(), 48);
    assert_eq!(child_type.decimal(), 30);
}

