fn test_cast_func_sig_null_and_hybrid() {
    // NULL passes through the string cast still NULL.
    let ctx = WarningCtx::default();
    let out = cast_eval(
        "cast_char",
        const_typed(Datum::Null, real_ft()),
        str_ft(),
