    // value (Go enum{Name:"a", Value:0} → 0).
    let out = cast_eval(
        "cast_signed",
        const_typed(
            Datum::Enum(MysqlEnum::new("a", 0), Collation::Utf8Mb4Bin),
            FieldType::new(C::Enum),
