        const_typed(Datum::Time(tm.clone()), FieldType::new(C::Datetime)),
        &ctx,
    );
    assert_eq!(i, 20201010101010);
    assert!((r - 20201010101010.0).abs() < 1e-3);
    assert_eq!(d.storage_string(), "20201010101010");
    assert_eq!(s, "2020-10-10 10:10:10");

