        json_call("JSON_SET", &[Datum::Null, Datum::Null, Datum::Null]).unwrap(),
        Datum::Null
    );
    json_eq(
        &json_call("JSON_SET", &[json_s("{}"), json_s("$.a"), Datum::Int(3)]).unwrap(),
        r#"{"a": 3}"#,
