    );
    for (doc, cand, want) in [
        ("{}", "{}", 1),
        (r#"{"a":1}"#, "{}", 1),
        (r#"{"a":1}"#, "1", 0),
        (r#"{"a":[1]}"#, "[1]", 0),
        (r#"{"b":2, "c":3}"#, r#"{"c":3}"#, 1),
