        ("VEC_DIMS", vec![Datum::Null], "NULL"),
        ("VEC_L2_NORM", vec![vector_of(&[3.0, 4.0])], "FLOAT:5"),
        ("VEC_L2_NORM", vec![Datum::Null], "NULL"),
        ("VEC_AS_TEXT", vec![vector_of(&[1.0, 2.0])], "STR:[1,2]"),
    ];
    for (name, args, want) in rows {
        assert_eq!(
