#[test]
fn pi_is_the_exact_f64_constant() {
    let got = math_dispatch_values("PI", &[], &WarnCountCtx::new())
        .expect("PI dispatches")
        .expect("PI evaluates");
    assert_eq!(got, Datum::Real(std::f64::consts::PI));
}

