fn test_lpad() {
    for (text, len, pad, want) in [
        ("hi", 5, "?", Some("???hi")),
        ("hi", 1, "?", Some("h")),
        ("hi", 0, "?", Some("")),
        ("hi", -1, "?", None),
        ("hi", 1, "", Some("h")),
        ("hi", 5, "", Some("")),
