/// Focused typed halves of Go's issue #56861 tables inside TestAddTimeSig /
/// TestSubTimeSig (DATE/DATETIME x STRING/DURATION). Constant-folded calls
/// must preserve the parsed right-operand FSP, while malformed string
/// operands answer SQL NULL. The full boundary-date matrix remains a separate
/// receipt item until all of its fixture rows are carried.
#[test]
fn test_add_sub_time_issue_56861_typed_tables() {
    let datetime = datetime_of(2024, 11, 1, 0, 0, 0);
    let got = eval_scalar(
        "ADDTIME",
        FieldType::new(FieldTypeCode::Datetime),
        vec![
            const_arg_typed(datetime.clone(), FieldType::new(FieldTypeCode::Datetime)),
            const_arg_typed(
                Datum::new_string("12:00:01.341300"),
                FieldType::new(FieldTypeCode::VarString),
            ),
        ],
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&got), "2024-11-01 12:00:01.341300");

    let got = eval_scalar(
        "ADDTIME",
        FieldType::new(FieldTypeCode::Datetime),
        vec![
            const_arg_typed(datetime.clone(), FieldType::new(FieldTypeCode::Datetime)),
            const_arg_typed(
                Datum::new_string("anuverivr"),
                FieldType::new(FieldTypeCode::VarString),
            ),
        ],
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&got), "<null>");

    let got = eval_scalar(
        "SUBTIME",
        FieldType::new(FieldTypeCode::Datetime),
        vec![
            const_arg_typed(datetime.clone(), FieldType::new(FieldTypeCode::Datetime)),
            const_arg_typed(
                Datum::new_string("12:00:01.341300"),
                FieldType::new(FieldTypeCode::VarString),
            ),
        ],
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&got), "2024-10-31 11:59:58.658700");

    let got = eval_scalar(
        "ADDTIME",
        FieldType::new(FieldTypeCode::String),
        vec![
            const_arg_typed(date_of(2024, 11, 1), FieldType::new(FieldTypeCode::Date)),
            const_arg_typed(
                Datum::new_string("12:00:01.341300"),
                FieldType::new(FieldTypeCode::VarString),
            ),
        ],
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&got), "2024-11-01 12:00:01.341300");

    let got = eval_scalar(
        "ADDTIME",
        FieldType::new(FieldTypeCode::String),
        vec![
            const_arg_typed(date_of(2024, 11, 1), FieldType::new(FieldTypeCode::Date)),
            const_arg_typed(
                Datum::new_string("12:00:01.000000"),
                FieldType::new(FieldTypeCode::VarString),
            ),
        ],
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&got), "2024-11-01 12:00:01");

    let got = eval_scalar(
        "SUBTIME",
        FieldType::new(FieldTypeCode::String),
        vec![
            const_arg_typed(date_of(2024, 11, 1), FieldType::new(FieldTypeCode::Date)),
            const_arg_typed(
                Datum::new_string("12:00:01.000000"),
                FieldType::new(FieldTypeCode::VarString),
            ),
        ],
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&got), "2024-10-31 11:59:59");

    // The vectorized DATETIME+TIME arm deliberately forces Fsp=-1, while
    // constant folding follows Go's row body and preserves the duration FSP.
    let duration =
        Datum::Duration(MySqlDuration::new(12, 0, 1, 341300, 6).expect("valid duration"));
    let vector = crate::time_fn::add_sub::add_sub_time(
        &[datetime.clone(), duration.clone()],
        [
            crate::time_fn::add_sub::TemporalKind::Datetime,
            crate::time_fn::add_sub::TemporalKind::Duration,
        ],
        1,
        false,
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&vector), "2024-11-01 12:00:01");
    let folded = crate::time_fn::add_sub::add_sub_time(
        &[datetime, duration],
        [
            crate::time_fn::add_sub::TemporalKind::Datetime,
            crate::time_fn::add_sub::TemporalKind::Duration,
        ],
        1,
        true,
        &NoColumns,
    )
    .unwrap();
    assert_eq!(got_text(&folded), "2024-11-01 12:00:01.341300");
}

/// Go `pkg/expression/builtin_time_test.go:1610 TestFromUnixTime` under a
/// pinned UTC session zone: integral and DECIMAL fractions rounding at fsp6
/// boundaries (.9999999 rolls into the next second), the `%Y %D %M %h:%i:%s %x`
/// format composition compared against DATE_FORMAT applied to the expected
/// string exactly like master does, negative input NULL, and the
/// TestIssue22206 upper bounds.
#[test]
fn test_from_unixtime_utc_fixed() {
    let utc = UtcClockCtx::new(0);
    let call = |args: Vec<Datum>| {
        time_fn::dispatch("FROM_UNIXTIME", &args, &utc)
            .expect("FROM_UNIXTIME belongs to this family")
            .map(|d| got_text(&d))
    };
    assert_eq!(
        call(vec![Datum::Int(1_451_606_400)]),
        Ok("2016-01-01 00:00:00".into())
    );
    for fraction in ["1451606400.123456", "1451606400.999999"] {
        let want = match fraction {
            "1451606400.123456" => "2016-01-01 00:00:00.123456",
            _ => "2016-01-01 00:00:00.999999",
        };
        let args = vec![Datum::Decimal(tidb_datatype::Decimal::from_literal(
            fraction,
        ))];
        assert_eq!(call(args), Ok(want.to_string()), "{fraction}");
    }
    // A scale-7 decimal rounds half-up into the next second.
    assert_eq!(
        call(vec![Datum::Decimal(tidb_datatype::Decimal::from_literal(
            "1451606400.9999999"
        ))]),
        Ok("2016-01-01 00:00:01.000000".to_string())
    );
    // TestIssue22206 far-future integral bound.
    assert_eq!(
        call(vec![Datum::Int(5_000_000_000)]),
        Ok("2128-06-11 08:53:20".to_string())
    );
    // Master compares formatted output against DATE_FORMAT(expect) itself;
    // mirror that contract on this tier.
    let fmt = "%Y %D %M %h:%i:%s %x";
    let two_arg = |arg: Datum| {
        got_text(
            &time_fn::dispatch("FROM_UNIXTIME", &[arg, Datum::new_string(fmt)], &utc)
                .unwrap()
                .unwrap(),
        )
    };
    let oracle = |text: &str| {
        got_text(
            &time_fn::calendar::date_format(&Datum::new_string(text), &Datum::new_string(fmt))
                .unwrap(),
        )
    };
    assert_eq!(
        two_arg(Datum::Int(1_451_606_400)),
        oracle("2016-01-01 00:00:00")
    );
    assert_eq!(
        two_arg(Datum::Decimal(tidb_datatype::Decimal::from_literal(
            "1451606400.123456"
        ))),
        oracle("2016-01-01 00:00:00.123456")
    );
    // Out-of-domain inputs answer SQL NULL.
    assert_eq!(call(vec![Datum::Int(-12_345)]), Ok("<null>".into()));
    assert_eq!(call(vec![Datum::Int(32_536_771_200)]), Ok("<null>".into()));
}

